-- CapCentral Caps subcategory migration and import of the existing static cap cards.
-- BACK UP your database first. Run this file ONCE in the Cap-Central database.
ALTER TABLE products ADD COLUMN cap_type VARCHAR(60) NULL AFTER category;

-- Assign current database Caps to the correct type when their name/image identifies it.
UPDATE products SET cap_type = CASE
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%bongol%' OR LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%bongool%' THEN 'Bongol'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%atiku%' THEN 'Atiku'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%tinubu%' OR LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%fila%' THEN 'Tinubu/Fila'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%miyaram%' OR LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%miyaaram%' THEN 'Miyaram'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%kindea%' THEN 'Kindea'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%tangaran%' THEN 'Tangaran'
  WHEN LOWER(CONCAT(COALESCE(name,''),' ',COALESCE(image_url,''))) LIKE '%tonak%' THEN 'Tonak'
  ELSE 'Zanna Bukar' END WHERE category = 'Caps' AND (cap_type IS NULL OR cap_type = '');

-- Import the products previously hard-coded in the seven cap subcategory HTML pages.
-- INSERT IGNORE keeps any existing product with the same generated product code unchanged.

-- Imported legacy caps start with stock_quantity=1 because each cap is a unique physical item.
-- Check the Admin Products page and adjust any product status/stock as needed.
